import{_ as s,a,c as t,ac as o}from"./chunks/framework.BSuaGltH.js";const m=JSON.parse('{"title":"第一册：英语初阶 · 单元 5 复习与自测 · 第97–103课","description":"L97–L120 原创练习和答案解析。","frontmatter":{"title":"第一册：英语初阶 · 单元 5 复习与自测 · 第97–103课","description":"L97–L120 原创练习和答案解析。","splitFrom":"life/english/new-concept/book-1/unit-05/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第一册：英语初阶 · 单元 5 复习与自测","summary":"L97–L120 原创练习和答案解析。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · 单元 5 复习与自测","link":"/life/english/new-concept/book-1/unit-05/review"},"next":{"text":"第一册：英语初阶 · 单元 5 复习与自测 · 第104–110课","link":"/life/english/new-concept/book-1/unit-05/review-part-02"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · 单元 5 复习与自测","link":"/life/english/new-concept/book-1/unit-05/review"},"next":{"text":"第一册：英语初阶 · 单元 5 复习与自测 · 第104–110课","link":"/life/english/new-concept/book-1/unit-05/review-part-02"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-05/review-part-01.md","filePath":"life/english/new-concept/book-1/unit-05/review-part-01.md"}'),r={name:"life/english/new-concept/book-1/unit-05/review-part-01.md"};function n(i,e,l,h,p,c){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="第一册-英语初阶-·-单元-5-复习与自测-·-第97–103课" tabindex="-1">第一册：英语初阶 · 单元 5 复习与自测 · 第97–103课 <a class="header-anchor" href="#第一册-英语初阶-·-单元-5-复习与自测-·-第97–103课" aria-label="Permalink to &quot;第一册：英语初阶 · 单元 5 复习与自测 · 第97–103课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-1/unit-05/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-1/unit-05/overview">单元导读</a> · <a href="/life/english/new-concept/book-1/unit-05/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-1/unit-05/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-1/unit-05/review">单元复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="第一册-英语初阶-·-单元-5-复习与自测" tabindex="-1">第一册：英语初阶 · 单元 5 复习与自测 <a class="header-anchor" href="#第一册-英语初阶-·-单元-5-复习与自测" aria-label="Permalink to &quot;第一册：英语初阶 · 单元 5 复习与自测 {#第一册-英语初阶-·-单元-5-复习与自测}&quot;">​</a></h2><p><a href="/life/english/new-concept/book-1/unit-05/overview">单元导读</a> · <a href="/life/english/new-concept/book-1/unit-05/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-1/unit-05/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-1/unit-05/review">单元复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-97-·-名词性物主代词" tabindex="-1">Lesson 97 · 名词性物主代词 <a class="header-anchor" href="#lesson-97-·-名词性物主代词" aria-label="Permalink to &quot;Lesson 97 · 名词性物主代词 {#lesson-97-·-名词性物主代词}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The small green suitcase is mine.</p><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1 {#练习-1}&quot;">​</a></h3><p>选择 my/mine：The suitcase is ___.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> mine</p><p><strong>解析：</strong> 按本课规则判断：my/your/her/our/their 后面接名词；mine/yours/hers/ours/theirs 本身能代表“某人的东西”，后面不再接名词。his 两种用法同形。Whose is this case? 可答 It is mine。物主代词随拥有者变化，不随被拥有的东西变复数；两只箱子属于我仍用 mine。多个形容词修饰名词时，尺寸常在颜色前。</p></details><p><strong>表达迁移：</strong> 围绕“辨认行李并确认归属”写两至三句，再读给同伴听。至少使用一次名词性物主代词，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The small green suitcase is mine. Are these keys yours or hers?</p><p>The small green suitcase 是主语，small 表尺寸、green 表颜色；mine 独立作表语，后不再接 suitcase。 These keys 为复数主语，are 前置；yours 与 hers 都独立代表“某人的钥匙”，两者之间用 or 提供选择。</p></details><p><a href="/life/english/new-concept/book-1/unit-05/lesson-097">回看本课</a></p><h2 id="lesson-98-·-名词性物主代词" tabindex="-1">Lesson 98 · 名词性物主代词 <a class="header-anchor" href="#lesson-98-·-名词性物主代词" aria-label="Permalink to &quot;Lesson 98 · 名词性物主代词 {#lesson-98-·-名词性物主代词}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Are these keys yours or hers?</p><h3 id="练习-1-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-1" aria-label="Permalink to &quot;练习 1 {#练习-1-1}&quot;">​</a></h3><p>选择 her/hers：Are these keys ___?</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> hers</p><p><strong>解析：</strong> 按本课规则判断：my/your/her/our/their 后面接名词；mine/yours/hers/ours/theirs 本身能代表“某人的东西”，后面不再接名词。his 两种用法同形。Whose is this case? 可答 It is mine。物主代词随拥有者变化，不随被拥有的东西变复数；两只箱子属于我仍用 mine。多个形容词修饰名词时，尺寸常在颜色前。</p></details><p><strong>表达迁移：</strong> 围绕“辨认行李并确认归属”写两至三句，再读给同伴听。至少使用一次名词性物主代词，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Are these keys yours or hers? The small green suitcase is mine.</p><p>These keys 为复数主语，are 前置；yours 与 hers 都独立代表“某人的钥匙”，两者之间用 or 提供选择。 The small green suitcase 是主语，small 表尺寸、green 表颜色；mine 独立作表语，后不再接 suitcase。</p></details><p><a href="/life/english/new-concept/book-1/unit-05/lesson-098">回看本课</a></p><h2 id="lesson-99-·-现在时引述与宾语从句" tabindex="-1">Lesson 99 · 现在时引述与宾语从句 <a class="header-anchor" href="#lesson-99-·-现在时引述与宾语从句" aria-label="Permalink to &quot;Lesson 99 · 现在时引述与宾语从句 {#lesson-99-·-现在时引述与宾语从句}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Ben says that his ankle hurts.</p><h3 id="练习-1-2" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-2" aria-label="Permalink to &quot;练习 1 {#练习-1-2}&quot;">​</a></h3><p>选择 says/tells：Ben ___ that his ankle hurts.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> says</p><p><strong>解析：</strong> 按本课规则判断：say 后可以接 that 引导的内容从句，that 在口语中常省略。主句为一般现在时 says 时，从句根据实际时间选择时态，不自动变过去。tell 通常需要人作宾语，如 tells me that ...；say 不能直接接人作宾语说 say me。宾语从句内部保留陈述语序，即使它含疑问意义也不能随意倒装。</p></details><p><strong>表达迁移：</strong> 围绕“转述别人正在说的内容”写两至三句，再读给同伴听。至少使用一次现在时引述与宾语从句，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Ben says that his ankle hurts. She tells me that the floor is wet.</p><p>Ben says 是主句，that his ankle hurts 是宾语从句；ankle 单数，所以从句谓语 hurt 加 s。 Tells 后接 me 表听话人，再接 that 从句；the floor is wet 使用完整陈述语序。</p></details><p><a href="/life/english/new-concept/book-1/unit-05/lesson-099">回看本课</a></p><h2 id="lesson-100-·-现在时引述与宾语从句" tabindex="-1">Lesson 100 · 现在时引述与宾语从句 <a class="header-anchor" href="#lesson-100-·-现在时引述与宾语从句" aria-label="Permalink to &quot;Lesson 100 · 现在时引述与宾语从句 {#lesson-100-·-现在时引述与宾语从句}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> She tells me that the floor is wet.</p><h3 id="练习-1-3" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-3" aria-label="Permalink to &quot;练习 1 {#练习-1-3}&quot;">​</a></h3><p>选择 says/tells：She ___ me that the floor is wet.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> tells</p><p><strong>解析：</strong> 按本课规则判断：say 后可以接 that 引导的内容从句，that 在口语中常省略。主句为一般现在时 says 时，从句根据实际时间选择时态，不自动变过去。tell 通常需要人作宾语，如 tells me that ...；say 不能直接接人作宾语说 say me。宾语从句内部保留陈述语序，即使它含疑问意义也不能随意倒装。</p></details><p><strong>表达迁移：</strong> 围绕“转述别人正在说的内容”写两至三句，再读给同伴听。至少使用一次现在时引述与宾语从句，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>She tells me that the floor is wet. Ben says that his ankle hurts.</p><p>Tells 后接 me 表听话人，再接 that 从句；the floor is wet 使用完整陈述语序。 Ben says 是主句，that his ankle hurts 是宾语从句；ankle 单数，所以从句谓语 hurt 加 s。</p></details><p><a href="/life/english/new-concept/book-1/unit-05/lesson-100">回看本课</a></p><h2 id="lesson-101-·-间接引语中的人称转换" tabindex="-1">Lesson 101 · 间接引语中的人称转换 <a class="header-anchor" href="#lesson-101-·-间接引语中的人称转换" aria-label="Permalink to &quot;Lesson 101 · 间接引语中的人称转换 {#lesson-101-·-间接引语中的人称转换}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Rita says she is staying with her aunt.</p><h3 id="练习-1-4" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-4" aria-label="Permalink to &quot;练习 1 {#练习-1-4}&quot;">​</a></h3><p>Rita says, &quot;I am tired.&quot; 改为间接引语。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Rita says she is tired.</p><p><strong>解析：</strong> 按本课规则判断：把别人第一人称的话转述出来时，应按实际身份转换 I、my、we 等代词，而不是固定一律变 he。主句 says 为现在时，从句可保留原来的时态；说话者的 I 如果指 Rita，转述可用 she。时间地点词是否改变取决于转述发生的时间和地点，不是见到间接引语就机械替换全部词。</p></details><p><strong>表达迁移：</strong> 围绕“转述信件内容并调整人称”写两至三句，再读给同伴听。至少使用一次间接引语中的人称转换，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Rita says she is staying with her aunt. The boys say they will arrive tomorrow.</p><p>Rita says 是现在时引述；she 与 her 都指 Rita，is staying 描述她现阶段的居住安排。 The boys say 是复数主语和原形谓语；从句 they will arrive 表将来，tomorrow 按当前转述时间理解。</p></details><p><a href="/life/english/new-concept/book-1/unit-05/lesson-101">回看本课</a></p><h2 id="lesson-102-·-间接引语中的人称转换" tabindex="-1">Lesson 102 · 间接引语中的人称转换 <a class="header-anchor" href="#lesson-102-·-间接引语中的人称转换" aria-label="Permalink to &quot;Lesson 102 · 间接引语中的人称转换 {#lesson-102-·-间接引语中的人称转换}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The boys say they will arrive tomorrow.</p><h3 id="练习-1-5" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-5" aria-label="Permalink to &quot;练习 1 {#练习-1-5}&quot;">​</a></h3><p>The boys say, &quot;We will arrive.&quot; 改为间接引语。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The boys say they will arrive.</p><p><strong>解析：</strong> 按本课规则判断：把别人第一人称的话转述出来时，应按实际身份转换 I、my、we 等代词，而不是固定一律变 he。主句 says 为现在时，从句可保留原来的时态；说话者的 I 如果指 Rita，转述可用 she。时间地点词是否改变取决于转述发生的时间和地点，不是见到间接引语就机械替换全部词。</p></details><p><strong>表达迁移：</strong> 围绕“转述信件内容并调整人称”写两至三句，再读给同伴听。至少使用一次间接引语中的人称转换，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The boys say they will arrive tomorrow. Rita says she is staying with her aunt.</p><p>The boys say 是复数主语和原形谓语；从句 they will arrive 表将来，tomorrow 按当前转述时间理解。 Rita says 是现在时引述；she 与 her 都指 Rita，is staying 描述她现阶段的居住安排。</p></details><p><a href="/life/english/new-concept/book-1/unit-05/lesson-102">回看本课</a></p><h2 id="lesson-103-·-too-very-enough" tabindex="-1">Lesson 103 · too/very/enough <a class="header-anchor" href="#lesson-103-·-too-very-enough" aria-label="Permalink to &quot;Lesson 103 · too/very/enough {#lesson-103-·-too-very-enough}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The instructions are clear enough to follow.</p><h3 id="练习-1-6" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-6" aria-label="Permalink to &quot;练习 1 {#练习-1-6}&quot;">​</a></h3><p>排序：clear / enough.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> clear enough</p><p><strong>解析：</strong> 按本课规则判断：very 只是加强程度，too 通常表示超过合适范围、带来困难；enough 表足够。enough 修饰形容词或副词时放后面，如 easy enough；修饰名词时放前面，如 enough time。too ... to ... 表太……而不能，形容词或副词后接不定式说明结果。不要把 very difficult 误解为一定无法完成。</p></details><p><strong>表达迁移：</strong> 围绕“评价难度和完成任务的能力”写两至三句，再读给同伴听。至少使用一次too/very/enough，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The instructions are clear enough to follow. This suitcase is too heavy for me to lift.</p><p>Clear 是表语，enough 放在形容词之后；to follow 说明足够清楚所能完成的活动。 Too heavy 表超过能力范围；for me 指动作执行者，to lift 给出因太重而无法完成的动作。</p></details><p><a href="/life/english/new-concept/book-1/unit-05/lesson-103">回看本课</a></p>',63)])])}const g=s(r,[["render",n]]);export{m as __pageData,g as default};
